quests[42880] = { id = 42880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting their Quota" }
quests[42881] = { id = 42881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lady Liadrin", objectives = "Good tidings, {name}. I am told that you seek to stop the demon's reign of terror. Is this true?\n\nThe Legion has hunted our people across countless worlds... taken countless lives. With each of our paladins that falls the Light reels in pain.\n\nI have had enough - I will fight by your side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42882] = { id = 42882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Massacre", description = "We have a single purpose here, to raise Sally Whitemane as a Death Knight of the Ebon Blade. Such is our goal and we will see it through.\n\nHowever, the Scarlet Crusade has terrorized the people of Azeroth long enough. Therefore, our work here this day will not be done until every crusader has fallen, every stone has crumbled, and every banner burned.\n\nCome, Deathlord, let us bring ruin upon the Scarlet Crusade.", progress = "The Scarlet Crusade shall burn.", completion = "The Scarlet Crusade will pay for their crimes. Soon the monastery shall fall, and with it so too does the Scarlet Crusade's last hope for survival.", objectives = "Slay 16 Scarlet Crusaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42883] = { id = 42883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Grell Broke Loose", description = "The grell are in a frenzy, attacking my brethren and destroying our village!\n\nPlease, stranger, help us send these wicked miscreants to the soil.", progress = "The grell can sometimes be a terrible nuisance.", completion = "Thank you, {name}. You are welcome in our village anytime.", objectives = "Slay 8 Wildeyed Undergrell in Grizzleweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42884] = { id = 42884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grassroots Effort", description = "When I arrived at my home, the front door was barred by magical roots.\n\nI was able to remove them, but few of my tribe possess the necessary ability to do so themselves.\n\nTake my staff. Its powers will easily disentangle the obstructing roots.", progress = "My old bones need more rest than I would care to admit.", completion = "The grell trapped our young within the huts. They are no longer at risk, thanks to your generous efforts.", objectives = "Use Old Grizzelback's Staff to destroy 5 snarled brambles in Grizzleweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42885] = { id = 42885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highlord's Command", description = "Tracking down the dreadlord Balnazzar is our highest priority. Let us send defenders of our order to pinpoint his recent movements.", progress = "Were you able to find anything?", completion = "Good. This intel will prove vital to our operations.", objectives = "Complete the mission, \"The Highlord's Command: Nemesis.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42886] = { id = 42886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Faronaar", description = "We are keeping a close eye on Legion movements at Faronaar in Azsuna.\n\nOur intel suggests that a high-ranking lieutenant, possibly the dreadlord Balnazzar himself, masterminds the attacks in that region.\n\nThis may be our chance to strike a blow at the Legion's leadership.\n\nVindicator Boros commands our forces at the front. He would welcome your help, Highlord.", completion = "Excellent, Highlord. You've arrived.", objectives = "Speak to Vindicator Boros along Old Coast Path.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42887] = { id = 42887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Retribution", description = "Anger seethes within me like smoldering coals.\n\nOne stoke, and that anger will flare into a roaring flame.\n\nThe Legion's attack on Exodar was just the motivation I needed, Highlord. I've watched my brethren die for the last time.\n\nNow, I will be the one who does the killing. I WILL have justice! Help me, Highlord, and slay any demons you encounter in lower Faronaar.", completion = "Glorious.", objectives = "Kill 20 demons in lower Faronaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42888] = { id = 42888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Communication Orbs", description = "We have important work at hand, Highlord.\n\nSpread out across the legion camp are orbs that are vital to the Legion's planning and strategy.\n\nDestroying them will severely damage their efforts. I will go with you, Highlord, to see this through.", progress = "Without a means of communicating, our enemy will be crippled.", completion = "No... we underestimated the enemy.", objectives = "Destroy 3 Legion Orbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42889] = { id = 42889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way Back Home", description = "Hello? This is Chief Telemancer Oculeth. I see you have emerged safely!\n\nI am locking in your location as we speak. I will need you to activate the beacon on your end so we can establish a teleportation link.\n\nGot it? Good.", completion = "When you suddenly vanished from our awareness we thought the worst.\n\nI do not know what to make of your adventures... I will need time to process this tragedy.\n\nRegardless, I am glad you are back safe and sound.", objectives = "Activate the beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42890] = { id = 42890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Command", description = "Boros is in serious trouble.\n\nThe fel lord, Jarvox, guards the pit to the west. Boros is trapped in there, too.\n\nWe need to defeat Jarvox, take the Codex of Command that he carries, and rescue Vindicator Boros.\n\nI am with you, Highlord!", progress = "Highlord, you have returned.", completion = "Our mission to Faronaar was successful, no thanks to me.\n\nI let my anger get out of control, and I would have paid for it dearly were it not for you.\n\nThank you, Highlord.", objectives = "Collect 1 Codex of Command and rescue Vindicator Boros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
