quests[42951] = { id = 42951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Glory of the Clans" }
quests[42952] = { id = 42952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Down the Skull", description = "The logbook contains the latest information on the Skull of the Man'ari. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", sourceObjective = "Take the logbook to Calydus in Dreadscar Rift.", sourceObjectiveStatus = "unverified-source-field" }
quests[42953] = { id = 42953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Soulbinder Halldora" }
quests[42954] = { id = 42954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Favor", description = "Meryl's illness is troubling. I have seen something similar before, but I cannot think of its name...\n\nTalk to my friend. I call her Ari. She has lived here in the Hall of the Guardian since it was last in use. If a tome on magical afflictions is to be found here, she would know where to look.", completion = "Books on magical illnesses? I might know where such a thing exists...", objectives = "Talk to Ari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42955] = { id = 42955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Proper Way of Things", description = "Archmage Khadgar is my friend. That he trusts you means much. \n\nI know of the book in which you seek, but it does not want to be found. It is old and angry and thirsts for power. We will have to convince it to emerge from hiding in the proper way. Perhaps if you bring it a gift of nightwell energy from the nightborne elves in Suramar City it will be mollified.", progress = "Have you found enough nightwell energy yet?", completion = "Power in its purest form. It is a lovely color, is it not? A fitting gift for a book of healing. Will you come out old one, now that you are no longer lost and forgotten?", objectives = "Siphon 50 phials of nightwell energy from the nightborne in Suramar City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42956] = { id = 42956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ari's Package", description = "Look! It was right here under our noses. \"Arcanists Guide to Rare Diseases.\" Sheepish thing. Most books just want to be dusted off and read from time to time. We will leave the phials of nightwell energy and it will go with you meekly enough.\n\nHere. I have packaged the book up for you to bring to Khadgar. I wrapped it in moth's wings to keep it soothed and light-hearted. And there is a gift for you. Just a small thing, really.", completion = "Ari found just the book I needed! And she included a ring for you as well.", objectives = "Bring Ari's package to Archmage Khadgar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42957] = { id = 42957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to the East", description = "My riddles you've solved but your job is not complete.\n\nCome, meet me at the Jade Serpent Temple for the answers you seek.", completion = "Ah, there the wikket is. Now, we see how well you can brew!", objectives = "Meet with the Monkey King at the Temple of the Jade Serpent within the Jade Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42958] = { id = 42958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 042 - Felblaze Ingress - Small" }
quests[42959] = { id = 42959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Is a Lucky Number", description = "Ari is much more than she appears, you know. She was once one of the most powerful archmagi on Azeroth and a member of the Council of Tirisfal. Unfortunately her mind was badly damaged and she has not left the Hall of the Guardian since.\n\nShe must like you very much to have given you a gift. If you bring her something special in return, I suspect she will surprise you. She prefers things in threes.", progress = "Have you found anything special for Ari yet?", completion = "These are wonderful! I couldn't keep them for myself, of course. But... Can you hear the bees humming in the honey brew? They sing so sweetly... Oh! What a lovely idea! Thank you, little friends.", objectives = "Bring Ari 3 special gifts. These gifts can be found on powerful enemies in dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42960] = { id = 42960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chose Strategy B" }
quests[42961] = { id = 42961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chose Strategy D" }
quests[42962] = { id = 42962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Correspondence", objectives = "Acquire 3 Stacks of Letters from Nightborne Couriers using the Nightborne Spellblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42963] = { id = 42963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Rulf Bonesnapper" }
quests[42964] = { id = 42964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Lagertha" }
quests[42966] = { id = 42966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highlord's Command", description = "Good decision, Highlord. We should be bolstering our forces by increasing recruitment efforts. Let us send our champions to carry out these orders.", completion = "Excellent work.", objectives = "Complete the mission, \"The Highlord's Command: Holy Allies.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42967] = { id = 42967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highlord's Command", description = "Well said, Highlord. The Legion is not one individual enemy - it is a massive beast with many heads.\n\nTo defeat them, we will need to stay vigilant on all fronts.\n\nLet us send our champions to deal with the Legion incursions as they come.", completion = "Well done. That should halt the Legion attacks for a while.", objectives = "Complete the mission, \"The Highlord's Command: Legion Defense.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42968] = { id = 42968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highlord's Command", description = "You are right, Highlord. Our military efforts cannot succeed without solid logistics.\n\nThat means we need a steady supply of weapons, food, medicine, and other provisions.\n\nLet us send our champions to establish a supply line.", completion = "Excellent. Our paladins will be well equipped for battle.", objectives = "Complete the mission, \"The Highlord's Command: Procuring Supplies.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42969] = { id = 42969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spy in Our Midst" }
quests[42970] = { id = 42970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Diamond King", description = "Me brother Magni, once King o' Ironforge, got changed into a diamond statue by a titan ritual. He's stood frozen in the belly o' the city fer years.\n\nBut I just got word that he's up and around... sayin' he knows somethin' 'bout how to beat the Legion!\n\nLook, {name}, I dunno if Magni's crazy, or if that's even really him. But if there's even a chance he kin help us...\n\nI'm told he muttered the name Ulduar. That's where I'm headed! I'd be obliged if you an' Khadgar were ta join me.", completion = "Magni's information was crucial to our efforts against the Legion. And it was good to see him again.\n\nNow to find that tome about the Pillars of Creation...", objectives = "Go with Brann and Khadgar to Ulduar and hear Magni Bronzebeard's message.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42971] = { id = 42971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Controlling the Elements", description = "Come closer, {race}.\n\nRagnaros in the Firelands, Al'Akir in his Throne of the Four Winds, and Neptulon in Throne of the Tides. They have been thorns in my hide since the world was new.\n\nProve to me your strength over the weaker elements, and I shall teach you how to display your power for all to see.", progress = "Prove your mastery over magic and the elements, {race}.", completion = "Now the other elements will truly fear you.", objectives = "Retrieve Remnants of Fire, Water, and Air, and reach Revered status with Therazane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42972] = { id = 42972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Poisoned" }
quests[42973] = { id = 42973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Rune of Razorice" }
quests[42974] = { id = 42974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Hodir", description = "It is time, {name}. Go to Azsuna and use the captured gateway to travel to Niskara and find Hodir.\n\nThe Legion will regret they set foot on Azeroth!", progress = "You've returned, {name}. What news do you bring?", completion = "I thank you, {name}. Without your help, one of Azeroth's mightiest guardians would have fallen into the hands of the Legion.\n\nYou have proven you are capable of leading my armies and defeating the Legion in their own territory.", objectives = "Join your forces at Felblaze Ingress and Complete the Fate of Hodir scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42975] = { id = 42975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Chain Armor" }
quests[42976] = { id = 42976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Ch 3 Tracking Quest" }
quests[42977] = { id = 42977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servant of the Windseeker", description = "The elemental lords must be united,  but there has been no Windlord to lead the air elementals since the death of Al'Akir.\n\nOnce, there was an heir to the Throne of Four winds named Prince Thunderaan, but the prince was defeated in the mortal realm and still awaits rebirth. Only one man holds the knowledge necessary to complete the prince's rebirth.\n\nThere is a servant of Thunderaan who wanders the sands of Silithus. Find him, and he will show you the way.", completion = "What does the Earthen Ring want with an old servant of the Windseeker?", objectives = "Speak with Highlord Demitrian in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42978] = { id = 42978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Audience", description = "{name},\n\nMy father lived by the sword, as you do. He taught me that if we truly want peace for our kingdom then we must be willing to fight to preserve it, as you have fought.\n\nYou have demonstrated valor of the highest order - bravery unsurpassed in the ranks of the Alliance. Valor that must be recognized.\n\nPlease join me in Stormwind Keep at once so that you can be properly rewarded for your service.\n\n- King Anduin Wrynn", completion = "It's an honor, {name}.", objectives = "Report to King Anduin Wrynn in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42980] = { id = 42980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Lumenstone 2" }
quests[42981] = { id = 42981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pure Water", description = "I may have discovered the key to restoring the pillar's magical energy.\n\nFirst, we will require a great deal of Pure Water. It is not easy to find, however I have heard that the naga in the Eye of Azshara are known to carry large quantities of this concentrated essence.\n\nIt will be not be easy, but if you can collect enough of the essence, we may be able to restore the pillar.", objectives = "Collect 10 Pure Water from naga and water elementals in the Eye of Azshara dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42982] = { id = 42982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Victor's Spoils", description = "It takes a true hero to put their life on the line day after day in defense of their home so that others do not have to.\n\nYou have dutifully safeguarded the people and interests of the Alliance, never faltering in your courage or devotion.\n\nAs a small token of our appreciation for your valiance, please turn to the gathered heroes before you, raise your weapon high, and be recognized.", progress = "Thank you, {name}. Thank you for everything.", completion = "Well-earned, {name}.", objectives = "Raise your weapon and be recognized in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42983] = { id = 42983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistral Essence", description = "To restore the Maelstrom Pillar, we will need to infuse it with the essence of air.\n\nA large quantity of Mistral Essence will be required to do this.\n\nMistral Essence can be found on many of the elementals in Vortex Pinnacle.\n\nIf you can return to me with a ready supply of elemental essence, I will be able to continue my restoration work on the Maelstrom Pillar.", progress = "Were you able to collect the necessary amount?", completion = "Excellent. You have exactly the right amount of Mistral Essence necessary to restore the pillar!", objectives = "Collect 100 Mistral Essences from wind elementals in Vortex Pinnacle. Travel to the Vortex Pinnacle through the portal in the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42984] = { id = 42984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: The Scepter of Storms", description = "The element of air can be difficult to contain. We will need a way to magically anchor it to the pillar.\n\nAir, no matter how capricious, cannot resist a good storm.\n\nIn the Eye of Azshara, the naga sorceress known as Lady Hatecoil possesses a powerful relic known as the Scepter of Storms.\n\nRetrieve the scepter, and we will use it to bind the elements of air to the Maelstrom Pillar.", progress = "I hope it was easy to convince Lady Hatecoil to part with her scepter.", completion = "Yes, this is it! With this, I will be able to bind the element of air nicely. And, maybe do some impressive tricks at future festivities.", objectives = "Collect the Scepter of Storms from Lady Hatecoil in the Eye of Azshara dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42985] = { id = 42985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Audience", description = "{name},\n\nThose who do not stand with the Horde stand against it. You, champion, have cut down such enemies in droves.\n\nI admire your dedication. It is through you that we will rise up, more powerful than ever, and put the Alliance in their place once and for all.\n\nJoin me in the Undercity at once. Your victories must be met with due reward.\n\n- Warchief Sylvanas Windrunner", completion = "The pleasure is mine, {name}.", objectives = "Report to Warchief Sylvanas Windrunner in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42986] = { id = 42986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies of Air", description = "Windlord Thunderaan has retaken the Vortex Pinnacle, but not all of his subjects have taken to his leadership kindly.\n\nIn his kingdom there is still unrest, and it appears there are four viziers who have risen up against him: Mistius, Zeph, Alacris, and Tulmos.\n\nWe will let Thunderaan focus on the war against the Burning Legion while we send our champions to aid Skywall against its enemies.", progress = "How are the missions going?", completion = "Excellent work, Farseer. With events in his realm calmed, Windlord Thunderaan can focus his efforts on the war effort.", objectives = "Complete 4 \"Thunderaan's Enemies\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42987] = { id = 42987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Victor's Spoils", description = "We will never be dominated so long as you stand at the front of our lines. Together we will slaughter anyone who stands in our way.\n\nYou have sacrificed as much as any in the name of the Horde. I will not let your dedication go unnoticed.\n\nFace your fellow champions, {name}. Face them, and be recognized.", progress = "You have pleased me this day.", completion = "You have impressed me, {name}. No simple feat.\n\nBe sure you continue to do so.", objectives = "Raise your weapon and be recognized in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42988] = { id = 42988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldmender", description = "The elements have gathered, and though the Firelands have yet to unite with us, we have more strength on our side than ever before.\n\nHowever, the war with the Burning Legion still rages, and for now we must turn our gaze to the Broken Isles.\n\nWhen we have dealt sufficiently with the immediate threats of the war, we will turn our attention to uniting the Firelands to our cause.", progress = "How does the situation look?", completion = "Impressive, truly impressive, Farseer! Everything I believed about your prowess has been proven true.\n\nYou have helped mend the rift caused by our enemies on the Broken Isles. We can rest easier, knowing what we have accomplished.", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42989] = { id = 42989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ma'haat the Indomitable", description = "In order to imbue the Maelstrom Pillar with the essence of earth, we will need one of the rarest fossils found on Azeroth - an egg.\n\nThe Egg of Gaiath is no ordinary egg; it contains the remnants of an unborn earthen primal, perfectly preserved in stone. There may be a means by which to revive it, but more on that later.\n\nFirst, we must find that egg!\n\nThe Earthen Ring has heard of an ancient being who possesses such an item, but he will require payment in blood!", completion = "<Ma'haat the Indomitable speaks with a low, rumbling voice>\n\nWhat... do you ask... of the earth?", objectives = "Speak to Ma'haat the Indomitable in Deepholm to acquire a Fossilized Egg. He will require Blood of Sargeras in trade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42990] = { id = 42990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: The Earthen Amulet", description = "That you were even able to acquire the Egg of Gaiath  is an incredible feat in itself, but the next step may well be impossible. Still... it is our only hope.\n\nFor the ritual to work, we will need to awaken the latent elemental energy resting inside of this egg.\n\nThere is an item that just may have the ability to do this - a relic known as the Earthen Amulet, rumored to have been created by Loken himself.\n\nIt was lost many ages ago, and has fallen into the hands of Dargrul the Underking.", progress = "Neltharion collected many valuable relics. The Earthen Amulet was one of them.", completion = "Yes, this is exactly what we need! I can get to work at once!", objectives = "Retrieve the Earthen Amulet from Dargrul the Underking in Neltharion's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42991] = { id = 42991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Runeseer Sigvid" }
quests[42992] = { id = 42992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Chain Armor" }
quests[42993] = { id = 42993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Ringmail Armor" }
quests[42994] = { id = 42994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Ringmail Armor" }
quests[42995] = { id = 42995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste For Blood", progress = "Such an egg is quite precious, fleshling. Yet, my hunger gnaws so deep...\n\nSuch a barter will cost you... greatly.\n\nBring me 5 Blood of Sargeras, and I will give you the egg.", completion = "<Ma'haat the Indomitable guzzles the Blood of Sargeras down his throat as he speaks.>\n\nYesh... thish ish... just what I wanted. The egg ish... yoursh!" }
quests[42996] = { id = 42996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maelstrom Pillar: Air", description = "Elementalist Janai was looking for you earlier, Farseer. It appears that her study of the Maelstrom Pillar has been most enlightening.\n\nIf you have a moment, you should go and meet with her to discuss her progress.", completion = "It is good to see you, Farseer. We have much to discuss!", objectives = "Speak to Elementalist Janai at the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42997] = { id = 42997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maelstrom Pillar: Earth", description = "Elementalist Janai has been hard at work restoring the Maelstrom Pillar. As of late, she has been focusing her research on the element of earth.\n\nYou should speak with her when you have a chance. I have heard that she is close to a breakthrough.", completion = "Ah, good timing Farseer! I was hoping you would come by.", objectives = "Speak to Elementalist Janai at the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42998] = { id = 42998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Return to Firelands 2 Mission Completed" }
