quests[43001] = { id = 43001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Return to Firelands 5 Mission Completed" }
quests[43002] = { id = 43002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessed Blade of the Windseeker", description = "So the Earthen Ring wishes to resurrect my master?\n\n<Highlord Demitrian laughs maniacally.>\n\nI knew this day would come! At last, humanity understands the power of the Windseeker!\n\nWhen Prince Thunderaan was slain at the hands of treacherous mortals, his soul was trapped within the sacred blade Thunderfury.\n\nTo resurrect my master you will need to find his sword and return it to Skywall. Last I heard, the betrayer who stole my master's sword traveled to the Broken Isles to fight demons.", progress = "Have you found the key to resurrecting Thunderaan?", completion = "This blade could indeed be the key to resurrecting the Windseeker. However, it has been damaged and the elemental soul within has diminished in power.\n\nTime may very well be running out...", objectives = "Locate the lost blade of the Windseeker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43003] = { id = 43003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Janai", description = "<Ma'haat the Indomitable speaks to you with a low, rumbling voice.>\n\nHere... is the Egg of Gaiath. It is yours now.\n\nGo... in peace.", completion = "It's true! The Egg of Gaiath does exist... right before my very eyes!", objectives = "Return to Elementalist Janai at the Heart of Azeroth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
