quests[43007] = { id = 43007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Chamber of Shadows", description = "Lord Jorach Ravenholdt sent me out to find you, {name}. He wants your counsel on some matter of importance.\n\nHe requests your presence back at the Chamber of Shadows.", completion = "It is good that Valeera was able to find you so quickly.\n\nThere is something important that you must immediately attend to.", objectives = "Speak with Lord Jorach Ravenholdt in the Chamber of Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
