quests[43011] = { id = 43011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Leather Armor" }
quests[43012] = { id = 43012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Leather Armor" }
quests[43013] = { id = 43013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The School of Roguery", description = "Great! Sounds like she's already settled in. That's good, cuz we already need some fresh meat for the grinder.\n\nYou should mosey over an' see if she's got any thieves just lying around takin' up space.", progress = "How's the new 'school' comin' along?", completion = "I saw. Not the healthiest-lookin' bunch, but I'm sure they'll do in a pinch.\n\nRegardless, they'll be out with Vanessa and Garona, so what could go wrong?", objectives = "Speak with Lonika Stillblade and train a Gang of Bandits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43014] = { id = 43014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Bad Wolfe", description = "You've heard of Winstone Wolfe, right? Of course you have. Who hasn't?\n\nSo, while you were off gabbin' with the headmistress, Lord Ravenholdt graced me with his presence. In the flesh. I didn't think he ever came out of that chamber.\n\nAnywhoodles, he more than suggested, in that way of his, that we send Garona, Vanessa, and our new merry gang of bandits off to have a little chat with The Wolf at Ravenholdt Manor.\n\nJust make sure they're nice and civil, or that's the last we'll see of them.", progress = "How'd the trip out to Ravenholdt Manor go?", completion = "Phew!\n\n<Nikki wipes her brow with a sense of relief.>\n\nWhatever we offered him, I'm glad he was agreeable. I can tell you if he wasn't happy, I'd be on the first flight off this rock for sure.", objectives = "Use the Scouting Map and complete the mission, \"The Big Bad Wolfe\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43015] = { id = 43015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Winstone Suggests", description = "If anyone can improve the way things run around here, it's Winstone Wolfe. I tell ya, the man is a miracle-worker!\n\nNow that he's workin' for us, shall we pick his brain an' see what he suggests?", progress = "I see that you were able to convince Mr. Wolfe to join us. Of course, that rather sizeable sum of gold we deposited into his bank account didn't hurt either.", completion = "Things are already looking up. But, of course, in my experience, there is always some amount of bad to temper the good.", objectives = "Speak to Winstone Wolfe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43016] = { id = 43016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
