quests[43054] = { id = 43054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ample Stockpile", description = "I have gone through our stockpile several times and no matter how I try to cut corners, we come up short.\n\nA lack of food and medicine will halt our war efforts... that is simply the reality.\n\nWe desperately need food or bandages. If you know how to acquire any such items, you can bring them to me.", completion = "Wonderful, yes yes! These supplies will fill our storehouse for weeks to come. Thank you so much, Grandmaster.", objectives = "Turn in 100 Spiced Rib Roasts, Highmountain Salmon, or Silkweave Bandages for Lao Shu's stockpile. The Cooking and First Aid professions may be useful for this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43055] = { id = 43055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
