quests[43058] = { id = 43058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiced Rib Roast", progress = "Spiced Rib Roast is a light meal that can be made by those skilled in cooking. If you are not learned in this profession, you may be able to acquire the services of a cook elsewhere.", completion = "Yes, these will do nicely. I'll get them salted and cured right away!" }
quests[43059] = { id = 43059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Fjordun" }
quests[43060] = { id = 43060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highmountain Salmon", progress = "This delicious fish can be found in the pools of Highmountain. Taking up fishing can be a productive and rewarding profession. Or, I hear there are plenty of fishers who are open to trading.", completion = "What a beautiful catch! I've never seen fish this size! Thank you, Grand Master." }
quests[43061] = { id = 43061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silkweave Bandages", progress = "Did you procure any bandages?", completion = "These bandages will help save many lives. Thank you." }
quests[43062] = { id = 43062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Training", description = "You may be the Grandmaster, but mastery must be maintained through discipline.\n\nTo achieve perfect harmony, you must continue your training.\n\nI would like to see your form in practice, {name}. Go out and use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike. Through discipline, we find greatness.", progress = "To achieve mastery, we must hone ourselves tirelessly.", completion = "Very impressive indeed, {name}. I had no doubt that your form is still top notch.", objectives = "Use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike abilities 10 times each.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
