quests[43089] = { id = 43089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Combatant's Plate Armor" }
quests[43090] = { id = 43090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulduar's Oath", description = "I was once leader of all of the titanforged keepers of Azeroth.  We were charged by the Titans themselves to protect the world.\n\nOnce I gave up on the post of Prime Designate, I gave up any measure of influence over the other keepers.  Not even my own son, Thorim, is bound to heed my commands.\n\nThe Gjallarhorn comes from a time before our falling out, however.  A time of an ancient oath of honor.\n\nLet us invoke that oath -- I am certain Thorim will answer the call.", progress = "What news do you bring from Ulduar?", completion = "I thank you, {name}.  That Hodir is gone is unfortunate, but things could have gone much worse and thanks to you Ulduar did not fall to the Legion today.", objectives = "Ask Hymdall to sound the Gjallarhorn and request Thorim's assistance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
